// Runnable demo for the TemperatureSensor contract.
// The interface is declared here without the public keyword so that this one
// file compiles and runs on its own.
interface TemperatureSensor {
    int getCurrentTemperature();
}

// A fake sensor: no hardware, just a value we choose. This is the kind of
// object a unit test would use.
class StubSensor implements TemperatureSensor {
    private final int reading;

    StubSensor(int reading) {
        this.reading = reading;
    }

    @Override
    public int getCurrentTemperature() {
        return reading;
    }
}

// Business logic that depends only on the contract, never on a specific sensor.
class Thermostat {
    private final TemperatureSensor sensor;

    Thermostat(TemperatureSensor sensor) {
        this.sensor = sensor;
    }

    boolean shouldTurnOnHeat() {
        return sensor.getCurrentTemperature() < 18;
    }
}

public class SensorDemo {
    public static void main(String[] args) {
        TemperatureSensor coldRoom = new StubSensor(12);
        TemperatureSensor warmRoom = new StubSensor(25);

        System.out.println("Cold room reading: " + coldRoom.getCurrentTemperature());
        System.out.println("Heat on? " + new Thermostat(coldRoom).shouldTurnOnHeat());

        System.out.println("Warm room reading: " + warmRoom.getCurrentTemperature());
        System.out.println("Heat on? " + new Thermostat(warmRoom).shouldTurnOnHeat());
    }
}
